// A person's machine lock (#3399, specs/3399-machine-lock): its chain of entries, the root first. lock/get, and machine/lock to a machine.
type Lock struct {
	Person string `json:"person"`

	Entries []LockEntry `json:"entries"`
}

// lock/add (#3399): entries to put on the end of the caller's lock, in order. The first names the head as its previous; the control plane writes each with a conditional write on the head, so two entries cannot both follow one head.
type LockAdd struct {
	Entries []LockEntry `json:"entries"`
}

// What a lock entry says (#3399), as its signer wrote it: the JSON that LockEntry.body carries, byte for byte. v is 1. Every entry names its person and, except the root, previous: the SHA-256 of the entry before's body. signer is the P-256 signing key that signed it, X9.63. key is the root's first signing key, the client, machine or invite added, the key removed, or the recovery key's public half. sealingKey is a machine's (addMachine); id is the machine's id (addMachine), or the client's id that the control plane knows it by (root and addClient, #3543), so a machine names the device in its audit from the lock; clientKind is a client's (addClient: mac, remote or web); expires is an invite's; sealed is a recovery entry's (#3493, D4): the recovery key's private half, AES-256-GCM under a key made from the recovery secret the person keeps (a 12-byte nonce, then the sealed 32 bytes and the tag), so a new client that is typed the secret signs with it.
type LockBody struct {
	V int64 `json:"v"`

	Kind LockEntryKind `json:"kind"`

	Person string `json:"person"`

	Previous Data `json:"previous,omitzero"`

	Signer Data `json:"signer"`

	At Date `json:"at"`

	Key Data `json:"key"`

	SealingKey Data `json:"sealingKey,omitzero"`

	ID *string `json:"id,omitzero"`

	Name *string `json:"name,omitzero"`

	ClientKind *string `json:"clientKind,omitzero"`

	Expires *Date `json:"expires,omitzero"`

	Sealed Data `json:"sealed,omitzero"`
}

// A request signed for a machine (#3492), as the control plane keeps it and delivers it: the method, the params as the sender wrote them (text, so no byte of them changes on the way), and the signature.
type LockDelivery struct {
	Method string `json:"method"`

	Params string `json:"params"`

	Lock LockSignature `json:"lock"`
}

// One entry of a machine lock (#3399): body is a LockBody's JSON, kept as the signer wrote it, so no language has to write it again the same way. sig is ECDSA P-256 with SHA-256 over "agents-lock/1\n" then body, the 64 bytes r then s (as WebCrypto and CryptoKit's rawRepresentation write it). The entry's hash is the SHA-256 of body.
type LockEntry struct {
	Body Data `json:"body"`

	Sig Data `json:"sig"`
}

// What a lock entry changes (#3399): root names the first signing key; addClient a client's signing key; addMachine a machine's key and sealing key, signed by a signer or an invite; invite a one-use key that may add one machine; remove a client, machine or invite no longer trusted; recovery the recovery key, or a new one.
type LockEntryKind string

const LockEntryKindRoot LockEntryKind = "root"
const LockEntryKindAddClient LockEntryKind = "addClient"
const LockEntryKindAddMachine LockEntryKind = "addMachine"
const LockEntryKindInvite LockEntryKind = "invite"
const LockEntryKindRemove LockEntryKind = "remove"
const LockEntryKindRecovery LockEntryKind = "recovery"

// lock/get (#3399): with no person, the caller's own lock. With person, that person's: only an admin may read another's (#3491), to check the machine keys an org route is sealed to (specs/3399-machine-lock D7, D8).
type LockGet struct {
	Person *string `json:"person,omitzero"`
}

// Where a machine lock stands (#3399): how many entries it has, and head, the SHA-256 of the newest one's body. lock/add's answer, and control/lockChanged.
type LockHead struct {
	Count int64 `json:"count"`

	Head Data `json:"head"`
}

// lock/hello (#3492, specs/3399-machine-lock D6): a client opens a checked channel to a machine. key is its signing key (P-256, X9.63), which the machine's lock must name as a client; ephemeral is a new ECDH P-256 key for this channel alone; sig is ECDSA P-256 (r then s) with SHA-256 over "agents-lock-channel/1\nclient\n" then ephemeral.
type LockHello struct {
	Key Data `json:"key"`

	Ephemeral Data `json:"ephemeral"`

	Sig Data `json:"sig"`
}

// lock/hello's answer (#3492): key is the machine's own key, which the client's lock must name as an addMachine; ephemeral is the machine's new ECDH P-256 key; sig is ECDSA with the machine's key over "agents-lock-channel/1\nmachine\n", the client's ephemeral, the machine's ephemeral, then the client's key. Each side then makes a key for each direction with HKDF-SHA256 (the ECDH secret; salt the client's then the machine's ephemeral; info "agents-lock-channel/1 client" or "… machine"), and every request and answer carries "lock":{"n":…,"mac":…} last: HMAC-SHA256 over the count (8 bytes, big-endian) then the message without that member.
type LockHelloReply struct {
	Key Data `json:"key"`

	Ephemeral Data `json:"ephemeral"`

	Sig Data `json:"sig"`
}

// lock/join (#3490, specs/3399-machine-lock D2): a client that is not in its person's lock asks to be added. key is its signing key (P-256, X9.63); commitment is the SHA-256 of "agents-lock-join/1\n", key, then a 16-byte nonce that the client shows only after a signer sent its own (lock/joinReveal), so a control plane cannot try the six digits again and again.
type LockJoin struct {
	Key Data `json:"key"`

	Commitment Data `json:"commitment"`
}

// control/lockJoinDecided (#3490): how a request to join the lock ended: approved (a signer put the client's addClient on the lock), denied or expired.
type LockJoinDecided struct {
	Request string `json:"request"`

	Result string `json:"result"`
}

// lock/joinDeny (#3490): a signer says no, or the asking client gives up.
type LockJoinEnd struct {
	Request string `json:"request"`
}

// lock/joinAnswer (a signer's nonce, 16 bytes, sent once) and lock/joinReveal (the asking client's nonce, which must match its commitment) (#3490).
type LockJoinNonce struct {
	Request string `json:"request"`

	Nonce Data `json:"nonce"`
}

// lock/joinRequests and control/lockJoinRequested (#3490): a client asking to join its person's lock, to every client of that person, and sent again in place as it goes on. client is the asking client's id, so it knows its own. nonce is the signer's, once one sent it (lock/joinAnswer), and answeredBy is that signer's client id; reveal is the asking client's nonce, once it showed it. Each screen makes the six digits from key, reveal and nonce. machine is set when a machine asks (#3491, D3): client is then the machine's id, kind is unknown, and a signer approves it with an addMachine whose key and sealing key are both key, the machine's own.
type LockJoinRequest struct {
	Request string `json:"request"`

	Client string `json:"client"`

	Machine *MachineRef `json:"machine,omitzero"`

	Name string `json:"name"`

	Kind ClientKind `json:"kind"`

	Key Data `json:"key"`

	Commitment Data `json:"commitment"`

	Expires Date `json:"expires"`

	Nonce Data `json:"nonce,omitzero"`

	AnsweredBy *string `json:"answeredBy,omitzero"`

	Reveal Data `json:"reveal,omitzero"`
}

// lock/join's answer (#3490): the request, and when it ends unanswered.
type LockJoinStarted struct {
	Request string `json:"request"`

	Expires Date `json:"expires"`
}

// A request signed by its sender's own key (#3492, D6, D7): a client's kept request for a machine that is not there, or a machine's call to another of its person's machines. It goes as the request's "lock" member. sig is ECDSA P-256 (r then s) with SHA-256 over "agents-lock-request/1\n", to, "\n", at in decimal, "\n", the method, "\n", then the params as sent. to is the machine's id; a machine may leave it out for another machine it named by name. at is seconds since 1970. The machine refuses one whose key its lock does not name, older than a day, or seen before.
type LockSignature struct {
	To *string `json:"to,omitzero"`

	At int64 `json:"at"`

	Key Data `json:"key"`

	Sig Data `json:"sig"`
}

