// The rules a layer sets (#2957, data-model.md "PolicyRules"): the same shape on the organisation, your and a folder's layer (FR-002). Every field is optional: absent sets nothing.
type PolicyRules struct {
	PermissionMode *PermissionLevel `json:"permissionMode,omitzero"`

	PermissionRequests *ClientPermissionMode `json:"permissionRequests,omitzero"`

	Sandbox *SandboxChoice `json:"sandbox,omitzero"`

	Budgets *PolicyRuleBudgets `json:"budgets,omitzero"`

	Helpers *PolicyHelpers `json:"helpers,omitzero"`

	Workflows *PolicyWorkflows `json:"workflows,omitzero"`

	NoticeLimits *PolicyNoticeLimits `json:"noticeLimits,omitzero"`

	ArchiveMyChats *bool `json:"archiveMyChats,omitzero"`

	// A runtime not named is not allowed. Absent allows every runtime and model.
	Runtimes map[string]PolicyRuntimeRule `json:"runtimes,omitzero"`

	Marketplaces *PolicyMarketplaces `json:"marketplaces,omitzero"`

	Environment *PolicyEnvironment `json:"environment,omitzero"`
}

// One allowed runtime in a policy (#998).
type PolicyRuntimeRule struct {
	// The model ids allowed, with * at the end allowed (claude-sonnet-*). Absent allows every model.
	Models []string `json:"models,omitzero"`

	// The ways this runtime may reach the model (#999). Absent: every way. [orgKey, gateway] is the org path only.
	Reach []PolicyReach `json:"reach,omitzero"`
}

// policy/set (#998): the rules, and the rev the admin read. No rev when there was no policy. Refused changedElsewhere when another admin saved first.
type PolicySet struct {
	Policy OrgPolicy `json:"policy"`

	Rev *string `json:"rev,omitzero"`
}

// The mark on a choice a policy refuses or caps (#998, FR-010). layer names which layer decided (#2957, R8).
type PolicySetBy struct {
	By string `json:"by"`

	Rule string `json:"rule"`

	Words string `json:"words"`

	Layer *PolicyLayerRef `json:"layer,omitzero"`
}

// The control key's signature of a policy (#998, FR-004), kept at v1/policy.sig: ECDSA P-256 with SHA-256 (es256), over the policy's canonical JSON (keys sorted, no spaces). sig is the 64 bytes r then s.
type PolicySignature struct {
	Version int64 `json:"version"`

	// The first 8 bytes of the SHA-256 of the control key's X9.63 public key, base64url.
	KeyID string `json:"keyID"`

	Alg string `json:"alg"`

	Sig Data `json:"sig"`
}

// daemon/policyState and daemon/policyStateChanged (#998, T027): the organisation's policy as this machine follows it, so a client on the direct path draws the strip and the Policy pane. No version when this machine has no policy.
type PolicyState struct {
	Version *int64 `json:"version,omitzero"`

	// The rules in force here, with only this machine's person's raises.
	Policy *OrgPolicy `json:"policy,omitzero"`

	// The kill switch is on: this machine stops its turns and starts no work.
	StopAll bool `json:"stopAll"`

	// This machine had a policy from its organisation and has none it can trust now (missing, or it fails the signature check). It starts no work until it gets one.
	NoPolicy bool `json:"noPolicy"`

	// The capabilities the policy requires that this machine lacks (FR-014). It starts no work.
	Update []string `json:"update,omitzero"`

	// Why this machine starts no work now, when it starts none.
	Refusal *PolicyRefusal `json:"refusal,omitzero"`
}

// The kill switch (#998, FR-015): while on, every machine stops its turns and starts no work.
type PolicyStopAll struct {
	On bool `json:"on"`

	By AuditActor `json:"by"`

	At Date `json:"at"`

	Note *string `json:"note,omitzero"`
}

// policy/stopAll (#998): the kill switch on or off, with an optional note.
type PolicyStopAllRequest struct {
	On bool `json:"on"`

	Note *string `json:"note,omitzero"`
}

// policy/mine and control/policyChanged (#998): the policy in force, for any person, with only their own budget raises. No policy when none was ever set.
type PolicyView struct {
	Policy *OrgPolicy `json:"policy,omitzero"`
}

