// A problem report, ready to post (#3718): the new issue's title and body, and the GitHub page that opens it already filled in, so the person posts it from their own account. Every known token shape and every home folder in it is cut out (~ in place of a home), and nothing is sent anywhere: the client shows the body, then opens the url.
type ProblemReport struct {
	Title string `json:"title"`

	// Markdown: what happened, what the person expected, and the versions, the machine and the runtime; with the recent log lines when asked.
	Body string `json:"body"`

	// The repository's new-issue page with the title and body in its query. When the body is too long for a link, the oldest log lines are left out of the link first, then the end of the body.
	URL string `json:"url"`
}

// What the person wrote in Report a Problem, and which client it is (#3718).
type ProblemReportRequest struct {
	// What happened, in the person's words.
	Happened string `json:"happened"`

	// What the person expected.
	Expected string `json:"expected"`

	// The client and its version, such as "Mac window 0.17.0" or "Web page".
	Client string `json:"client"`

	// The client's OS, such as "macOS 26.1", or the browser's.
	ClientOS string `json:"clientOS"`

	// The runtime of the open session, when there is one.
	Runtime *string `json:"runtime,omitzero"`

	// Add this machine's recent daemon.log lines.
	WithLog bool `json:"withLog"`
}

// One process of processes/list (#3453): the daemon, a session's runtime, or a child of either.
type ProcessUsage struct {
	Pid int64 `json:"pid"`

	Parent int64 `json:"parent"`

	// 0 for the daemon; a child is one deeper than its parent.
	Depth int64 `json:"depth"`

	Name string `json:"name"`

	// Of one core, so more than 100 on several, over the same time as the machine's; 0 for a process the last ask did not list.
	CpuPercent float64 `json:"cpuPercent"`

	// Resident bytes.
	Memory int64 `json:"memory"`

	// The session whose runtime this is, or whose runtime started it.
	AgentId *UUID `json:"agentId,omitzero"`

	// That session's title, when it has one.
	Title *string `json:"title,omitzero"`
}

// processes/list (#3453): the machine's totals and the daemon's process tree, in tree order, the daemon first. At most 200 processes; omitted counts the rest.
type ProcessesState struct {
	Machine MachineUsage `json:"machine"`

	Processes []ProcessUsage `json:"processes"`

	Omitted int64 `json:"omitted"`
}

// A project (#2317): what people work on, the record that folders join. folders is what the machines last reported.
type Project struct {
	ID string `json:"id"`

	Name string `json:"name"`

	Owner string `json:"owner"`

	Folders []ProjectFolder `json:"folders"`

	// The caller is the owner or an admin, so may rename and remove it, and set its slots and boards.
	MayChange bool `json:"mayChange"`

	// The project's Tasks, Code review and CI (#2669), one per slot: every folder in the project uses them. A slot that is not here is each folder's own.
	Slots []ProjectSlot `json:"slots,omitzero"`

	// The boards in the project's Tasks slot (#3282), in their order. Absent with none.
	Boards []ProjectBoard `json:"boards,omitzero"`
}

// One board in a project's Tasks slot (#3282): a GitHub Projects board, a Jira board, a Linear team, a GitLab group board or an Azure Boards board (a team's, #3816), by its address and a name (the team's). Work's Issues and Features lists narrow to one. A client sends name and url; the control plane reads forge, key and site from the url.
type ProjectBoard struct {
	Name string `json:"name"`

	// The board's address on the web: github.com/orgs/<org>/projects/<n> (or users/<login>), <site>/jira/software/…/boards/<id>, linear.app/<workspace>/team/<KEY>, <gitlab>/groups/<group>/-/boards/<id>, or dev.azure.com/<org>/<project>/_boards/board/t/<team> (or an Azure DevOps Server's). It names the board in forge/issues' board.
	URL string `json:"url"`

	// github, atlassian (Jira), linear, gitlab or azuredevops (Azure Boards).
	Forge *ConnectionProvider `json:"forge,omitzero"`

	// The board on its forge: <owner>/<number> on GitHub, the board id on Jira, the team key on Linear, <group>#<id> on GitLab, <org>/<project>/<team> on Azure Boards.
	Key *string `json:"key,omitzero"`

	// The board's host: github.com, the Jira site, linear.app, gitlab.com or a self-managed GitLab, dev.azure.com or an Azure DevOps Server.
	Site *string `json:"site,omitzero"`
}

// projects/setBoards (#3282): the project's boards, all of them each time, in their order; none leaves Tasks with no boards. Only the owner or an admin. At most 20.
type ProjectBoardsSet struct {
	ID string `json:"id"`

	Boards []ProjectBoard `json:"boards"`
}

