// UnmarshalJSON reads a field that is missing as its default.
func (v *WorkflowSummary) UnmarshalJSON(b []byte) error {
	type plain WorkflowSummary
	p := plain{IsEnabled: true}
	if err := json.Unmarshal(b, &p); err != nil {
		return err
	}
	*v = WorkflowSummary(p)
	return nil
}

